def read_file_safe(path: str, max_chars: int = 15_000) -> str:
    try:
        content = Path(path).read_text(errors="replace")
        if len(content) > max_chars:
            content = content[:max_chars] + f"\n... (truncated at {max_chars} chars)"
        return content
    except OSError:
        return ""

